pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address nonOwner, uint256 val) public {
        vm.assume(nonOwner != c.Owner());
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(c));

        // Ensure contract has some balance to make withdrawal meaningful
        vm.deal(address(c), 1 ether);

        // Give the nonOwner enough Ether to call Command with val
        uint256 balBefore = address(c).balance;
        vm.assume(val >= balBefore);
        vm.deal(nonOwner, val);

        // The nonOwner calls Command with the value equal to the contract balance
        vm.prank(nonOwner);
        c.Command{value: val}(address(0), "");

        // Now attempt a withdrawal by the same nonOwner
        vm.prank(nonOwner);
        // In the reference, withdraw requires Owner, so it must revert.
        // In the mutant, withdraw has no check, so it succeeds and drains the contract.
        // We assert that after the withdrawal attempt, the contract balance is unchanged.
        // (If it reverted, balance stays the same; if it succeeded, balance changes.)
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore);
    }
}

