import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // 1. restrict to admissible domain: amount must be > 0 and not cause overflow
        vm.assume(amount > 0);
        vm.assume(address(c).balance + amount >= address(c).balance);
        vm.assume(address(c).balance + amount < 2**256 - 1);

        // 2. fund the contract with the fuzzed amount and set up owner
