        vm.deal(owner, 1 ether);

        // 3. owner withdraws
        vm.prank(owner);
        bool ok = true;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // 4. Assertion: after a successful withdrawal, the contract balance must be zero
        assertTrue(!ok || address(c).balance == 0);
    }
}

