pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 extraFunds) public {
        // Restrict the domain to avoid overflow in setup and to ensure the invariant is meaningful
        vm.assume(initialBalance > 0 && initialBalance <= address(this).balance);
        vm.assume(extraFunds <= type(uint256).max - initialBalance);

        // Fund the contract with the fuzzed amount
        vm.deal(address(c), initialBalance);

        // Record the contract's balance before withdrawal
        uint256 balanceBefore = address(c).balance;

        // The Owner (this test contract) calls withdraw()
        bool success = true;
        try c.withdraw() { success = true; } catch { success = false; }

        uint256 balanceAfter = address(c).balance;

        // If the call succeeded (revert would also be a difference, but the reference should not revert),
        // the reference must have reduced the balance; the mutant transfers 0, so balanceAfter == balanceBefore.
        assertTrue(!success || balanceAfter < balanceBefore);
    }
}

