pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 balanceBefore, uint256 extraAmount) public {
        // Admissible domain: balanceBefore fits in uint256, and total used Ether is reasonable.
        // The fuzzer provides both the initial contract balance and an extra amount sent with the call.
        // We convert the Owner here to an address we control.
        address owner = c.Owner();
        vm.assume(owner != address(0));
        // Bound balanceBefore to avoid overflow and to keep it within a feasible range, but keep it large.
        balanceBefore = bound(balanceBefore, 1, type(uint128).max);
        extraAmount = bound(extraAmount, 0, type(uint128).max);

        // Fund the contract to the specified balanceBefore
        vm.deal(address(c), balanceBefore);
        // Record Owner's balance before
        uint256 ownerBefore = owner.balance;

        // Owner calls withdraw; they may also send extra Ether along (msg.value).
        vm.deal(owner, extraAmount);
        vm.prank(owner);
        try c.withdraw{value: extraAmount}() {
            // withdraw succeeded
        } catch {
            // If it reverts, the rule does not apply; we just skip the assertion by returning.
            return;
        }

        // After a successful withdraw, the Owner's balance must have increased by exactly
        // the amount that the contract should have transferred: its entire pre-withdraw balance plus any msg.value sent.
        // The buggy withdraw does nothing, so the Owner's balance only decreases by gas costs.
        // We assert that the Owner's post-balance is >= ownerBefore + balanceBefore + extraAmount - tolerance.
        // Because gas is spent, we actually need to check a relative equality. Instead, we assert
        // that the Owner's balance after is strictly greater than their balance before,
        // and that the contract's balance is now 0.
        uint256 ownerAfter = owner.balance;
        assertTrue(address(c).balance == 0 && ownerAfter > ownerBefore);
    }
}

