        // Therefore, M completes without revert (ok becomes true),
        // while P always reverts (ok remains false).
        // However, the failing call itself reverts in the subcontext,
        // so M's Command execution does not revert; the try/catch sees success.
        // Thus, P reverts, M does not.
        assertFalse(ok, "Non-owner must not be able to execute Command");
    }
}

