contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes memory data, uint256 amount) public {
        vm.assume(adr != address(0));
        vm.assume(data.length > 0);

        // Ensure Owner has some Ether to call Command
        address owner = c.Owner();
        vm.deal(owner, amount);

        // Deploy an adversarial callee that fails to handle empty data or reverts, making any empty call to it fail.
        // The bug only manifests if the external call succeeds, so we need a callee that does NOT revert.
        // Actually, to make the difference observable: in the reference, adr receives the call and can succeed or fail.
        // In the bug, Owner receives the call. If adr is an EOA, adr.call always succeeds (return true).
        // So we need a case where adr is a helper that causes a failure on receiving Ether, but Owner receiving the same call does NOT fail.
        // Deploy a helper that reverts in fallback.
        Reverter reverter = new Reverter();
        // We'll pass reverter as adr to Command.
        // Command will be called by Owner (msg.sender == Owner).

        // Record Owner balance before
        uint256 ownerBalanceBefore = address(c).balance;
        // We need to give the contract Ether so that its balance reflects something
        vm.deal(address(c), 10 ether);
        ownerBalanceBefore = address(c).balance;

        // Prank as Owner and call Command with adr = reverter, value = amount, data = data
        vm.prank(owner);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("Command(address,bytes)", reverter, data));
        // Reference: adr.call{value: amount}(data) -> reverter.fallback reverts -> Command reverts -> Owner balance unchanged.
        // Bug: Owner.call{value: amount}(data) -> Owner is EOA, call succeeds -> Owner (which is the contract owner, an EOA) receives amount,
        // effectively transferring Ether out of the contract to the Owner address. This reduces contract balance by amount.

        // After the call, the contract balance should be the same as before if it reverted, OR might have changed if it succeeded.
        // The property: In the reference code, calling Command with a reverting adr always fails and leaves contract balance unchanged.
        // In the buggy code, it succeeds and transfers amount out, reducing contract balance.
        assertTrue(address(c).balance == ownerBalanceBefore || address(c).balance == ownerBalanceBefore + amount);
    }
}

