import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 callValue, uint256 initialBalance) public {
        vm.assume(adr != address(0) && adr != address(c));
        vm.assume(callValue > 0);
        vm.assume(initialBalance > 0);
        vm.deal(address(c), initialBalance);
        vm.deal(address(this), callValue);
        uint256 balanceBefore = address(c).balance;
        c.multiplicate{value: callValue}(adr);
        uint256 balanceAfter = address(c).balance;
        if (callValue >= balanceBefore) {
            assertTrue(balanceAfter == 0);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

