pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 msgValue, uint256 preBalance) public {
        // Bound msgValue to avoid potential overflow issues in require statement, but keep it wide.
        msgValue = bound(msgValue, 0, type(uint256).max - preBalance);
        // Ensure the condition msg.value >= address(this).balance is met so the function body executes.
        preBalance = bound(preBalance, 0, type(uint256).max / 2);
        vm.assume(msgValue >= preBalance);

        // Give the contract some initial balance.
        vm.deal(address(c), preBalance);
        // Give the caller enough ether.
        vm.deal(address(this), msgValue);

        // Execute multiplicate. We do not care if it reverts or not for the assertion.
        try c.multiplicate{value: msgValue}(adr) {} catch {}

        // Universal property: after any call to multiplicate that does not revert,
        // the contract's balance must be zero. The reference version sends the full balance,
        // the buggy version sends only msg.value, leaving residual ether.
        assertTrue(address(c).balance == 0);
    }
}

