pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, uint256 val, uint256 preFund) public {
        vm.assume(adr != address(0));
        vm.assume(adr != address(c));
        vm.assume(preFund <= type(uint256).max - val);
        // Fund the contract with some ether to set up balance
        vm.deal(address(this), preFund + val);
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: preFund}("");
        require(ok, "initial fund failed");
        // Record adr balance before call
        uint256 adrBalBefore = adr.balance;
        uint256 cBalBefore = address(c).balance;
        // Fuzzed caller sends val
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(adr, val, preFund)))));
        vm.assume(caller != address(0) && caller != address(c) && caller != adr);
        vm.deal(caller, val);
        vm.prank(caller);
        c.multiplicate{value: val}(adr);
        uint256 cBalAfter = address(c).balance;
        uint256 adrBalAfter = adr.balance;
        // Rule: if contract balance decreased to zero, adr must have received exactly the lost amount
        if (cBalAfter == 0 && cBalBefore > 0) {
            assertTrue(adrBalAfter - adrBalBefore == cBalBefore - cBalAfter);
        }
    }
}

