pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 msgValue, address adr) public {
        // Restrict domain to avoid overflow in balance arithmetic
        vm.assume(initialDeposit <= type(uint256).max / 2);
        vm.assume(msgValue <= type(uint256).max / 2);
        vm.assume(initialDeposit + msgValue <= type(uint256).max);

        // Ensure sender is not adr to observe the difference clearly
        address sender = address(0x1234);
        vm.assume(adr != sender);

        // Fund the contract
        vm.deal(address(c), initialDeposit);
        // Fund the sender
        vm.deal(sender, msgValue);

        // Record sender's balance before the call
        uint256 senderBalanceBefore = sender.balance;

        // Execute multiplicate as the sender
        vm.prank(sender);
        c.multiplicate{value: msgValue}(adr);

        // General rule: If the condition msg.value >= address(this).balance was true at the time of the call,
        // the caller (msg.sender) must NOT have received any ether from the contract.
        // Since the contract had initialDeposit before the call, the condition is initialDeposit <= msgValue.
        // The bug sends the contract balance + msgValue to msg.sender, which is not allowed in the reference.
        if (msgValue >= initialDeposit) {
            assertTrue(sender.balance <= senderBalanceBefore);
        }
    }
}

