pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 donation, uint256 callValue, address adr) public {
        // Bound callValue to prevent overflow in balance addition during fuzzing
        callValue = bound(callValue, 0, type(uint128).max);
        donation = bound(donation, 0, type(uint128).max - callValue);
        // Ensure adr is not the zero address
        vm.assume(adr != address(0));
        vm.assume(adr != address(c));

        // Give the contract some initial balance via a donation
        vm.deal(address(this), donation);
        vm.prank(address(this));
        (bool success,) = address(c).call{value: donation}("");
        require(success, "donation failed");

        uint256 balanceBefore = address(c).balance;

        // Call multiplicate with fuzzed msg.value
        vm.deal(address(this), callValue);
        vm.prank(address(this));
        try c.multiplicate{value: callValue}(adr) returns (bool) {
            // call succeeded
        } catch {
            // call reverted
        }

        uint256 balanceAfter = address(c).balance;

        // If the multiplicate condition was entered (callValue >= balanceBefore in reference,
        // callValue > balanceBefore in mutant), the reference transfers the whole balance,
        // leaving 0. The mutant fails to transfer when callValue == balanceBefore and leaves funds.
        assertTrue(
            balanceAfter == 0 || balanceAfter == balanceBefore
        );
    }
}

