import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address target) public {
        // Ensure we have enough funds to potentially trigger the condition
        vm.assume(amount >= address(c).balance);
        vm.assume(target != address(0) && target != address(c));

        // Fund the contract with same amount as will be sent, to ensure msg.value >= address(this).balance
        vm.deal(address(this), amount);
